// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// `prisma generate` never touches the database, so it must not hard-fail when
// DATABASE_URL is absent (fresh clone with no .env yet). The placeholder is
// only ever contacted by `migrate` / `db push`, which are commands that
// genuinely need a real connection string.
const databaseUrl =
  process.env.DATABASE_URL ?? "postgresql://localhost:5432/postgres";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: databaseUrl,
  },
});
